Definition room_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TOther pc => (negb (Z.eqb pc PML.PC_STR_PUSH_BACK) || EEK.contra_chk 69 (SR.ps_cells ps) || EEK.pred_chk 69 (SR.ps_cells ps) (fun cv => Z.ltb (P i) (esc_cls cv)))%bool
  | CC.TGoto _ _ => true
  end.
Lemma room_ok : CH2.leaves_all G.CPS G.TAGS room_chk = true.
Proof. vm_compute. reflexivity. Qed.

Section EscapeOk.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PML.fp_ok fx -> PML.fp_ok fx'.
Hypothesis PUSHB_OK : str_push_back_x_specU L HI.
Hypothesis TOCP_OK : to_codepoint_spec L.

(* [comment removed for export] *)
Section Stretch.
Variables (E0 : env) (sp S2 : Z).
Hypothesis U2 : bv_unsigned (ev E0 2) = sp.
Hypothesis SPR : hl_ceil L + 8640 <= sp /\ sp <= hl_sptop L /\ 0x7fff80000000 <= hl_sptop L <= 2 ^ 47.
Hypothesis S2R : sp <= S2 /\ S2 + 24 <= hl_sptop L.

