Lemma byte_val : forall E' (M' : mem) cells q n k bs, know_ok RSEGS E' M' cells -> byte_facts cells = true -> eb E' 0%nat = map (Z_to_bv 8) bs ->
  bv_unsigned (ev E' 10) = q -> bv_unsigned (ev E' 11) = n -> bv_unsigned (ev E' 48) = k -> n = len bs -> 1 <= k <= n -> 0 <= q -> q + n < 2 ^ 64 ->
  uv E' CE = (nth (Z.to_nat (n - k)) bs 0) mod 256 /\ 0 <= uv E' CE <= 255 /\ PML.u8 M' (q + (n - k)) (uv E' CE).
