Theorem escape_main_okU : forall (q : Z) (bs : list Z), 1 <= len bs ->
  stransU L HI PC_ESCAPE_STRING ESC_SCR
      (fun LBo _ R M SK => PML.a0 R q /\ PML.a1 R (len bs) /\ PML.a2 R 0 /\ PML.a3 R 0 /\ getr R 14%bv = Z_to_bv 64 SK /\
                         L5.bytes_at RSEGS M q bs /\ L5.defined M q (len bs) /\ in_blocks LBo q (len bs))
      (fun R' pay => PML.a0 R' pay) (fun pay => pay = esc_len bs) (esc_len bs).
Proof using HIok LAY FPM PUSHB_OK TOCP_OK.
  intros q bs Hbs LBo cr sp r SK S2 kx bx rep. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp (Hentry & (Ha0 & Ha1 & Ha2 & Ha3 & H14 & Hbq & Hdq & Hinb) & HSK & SK1 & SK2 & SKap & Hsink & HS2 & Himg & HSC & HROOM) Hcont.
  destruct Hentry as (Hra & Hraok & Hsp & Htp & Hstk). destruct Hstk as (S1 & S2' & S3 & S4 & S5).
  unfold ESC_SCR, STRX_SCR, PMS.STR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK in *. change (144 + (256 + (16 + 8224))) with 8640 in *.
  pose proof (PmLayout.ly_segs L LAY) as LS. pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  pose proof (PmLayout.ly_errno L LAY) as LER.
  pose proof HS2 as (OS1 & OS2 & OS3). unfold PML.apart in SKap. unfold in_blocks in Hinb.
  set (n := len bs) in *.
  set (len0 := len (PML.srep_chars rep)) in *.
  assert (CLO : 0x7fff7f800000 <= hl_ceil L) by (unfold hl_ceil; lia).
  assert (SRCB : exists b, In b LBo /\ block_range L (fst b) (snd b) /\ fst b <= q /\ q + n <= fst b + snd b).
  { destruct Hinb as [Hn0|(b & Hb & Hb1 & Hb2)]; [lia|].
    exists b. split; [exact Hb|]. split; [|lia].
    destruct (hio_wf L SCFG HI HIok _ _ _ _ HH) as (Hwf & _). apply (Hwf b). apply in_or_app. left. exact Hb. }
  assert (QB : 4096 <= q /\ q + n <= hl_ceil L).
  { destruct SRCB as (b & _ & (B1 & _ & _ & _ & B5) & B6 & B7). lia. }
  set (E0 := Env (reg_ev R (fun v => Z_to_bv 64 (nth (v - 32) [S2] 0))) (fun _ => map (Z_to_bv 8) bs)).
  assert (EV : forall x : reg, ev E0 (ridx x) = getr R x) by (intros x; apply CL5.ev_reg).
  assert (V2 : ev E0 2 = Z_to_bv 64 sp) by (rewrite <- Hsp; exact (EV 2%bv)).
  assert (V4 : ev E0 4 = Z_to_bv 64 PML.TP) by (rewrite <- Htp; exact (EV 4%bv)).
  assert (V10 : ev E0 10 = Z_to_bv 64 q) by (rewrite <- Ha0; exact (EV 10%bv)).
  assert (V11 : ev E0 11 = Z_to_bv 64 n) by (rewrite <- Ha1; exact (EV 11%bv)).
  assert (V12 : ev E0 12 = Z_to_bv 64 0) by (rewrite <- Ha2; exact (EV 12%bv)).
  assert (V13 : ev E0 13 = Z_to_bv 64 0) by (rewrite <- Ha3; exact (EV 13%bv)).
  assert (V14 : ev E0 14 = Z_to_bv 64 SK) by (rewrite <- H14; exact (EV 14%bv)).
  assert (V32 : ev E0 32 = Z_to_bv 64 S2) by reflexivity.
  assert (SCRV : CH.hd_scr G.HDECL = 8640) by reflexivity.
  assert (STKF : sp mod 16 = 0 /\ hl_ceil L + CH.hd_scr G.HDECL <= sp /\ sp <= hl_sptop L /\ 0x7fff80000000 <= hl_sptop L <= 2 ^ 47)
    by (rewrite SCRV; unfold hl_ceil; repeat split; lia).
  assert (SPR : hl_ceil L + 8640 <= sp /\ sp <= hl_sptop L /\ 0x7fff80000000 <= hl_sptop L <= 2 ^ 47) by (unfold hl_ceil; repeat split; lia).
  assert (S2R : sp <= S2 /\ S2 + 24 <= hl_sptop L) by (split; lia).
  assert (U2 : bv_unsigned (ev E0 2) = sp) by (rewrite V2; apply u64_of_Z; lia).
  assert (U10 : bv_unsigned (ev E0 10) = q) by (rewrite V10; apply u64_of_Z; lia).
  assert (U11 : bv_unsigned (ev E0 11) = n) by (rewrite V11; apply u64_of_Z; lia).
  assert (U12 : bv_unsigned (ev E0 12) = 0) by (rewrite V12; apply u64_of_Z; lia).
  assert (U13 : bv_unsigned (ev E0 13) = 0) by (rewrite V13; apply u64_of_Z; lia).
  assert (U14 : bv_unsigned (ev E0 14) = SK) by (rewrite V14; apply u64_of_Z; lia).
  assert (U32 : bv_unsigned (ev E0 32) = S2) by (rewrite V32; apply u64_of_Z; lia).
  assert (EB0 : eb E0 0%nat = map (Z_to_bv 8) bs) by reflexivity.
  assert (SCRP : 0 <= CH.hd_scr G.HDECL) by (rewrite SCRV; lia).
  assert (NF32 : (32 <= GT.NF)%nat) by (unfold GT.NF; lia).
  assert (TP0 : ev E0 4 = Z_to_bv 64 (hl_tp L)) by (rewrite V4, (PmLayout.ly_tp L LAY); reflexivity).
  set (W := [(S2, 24)]).
  assert (W_OK : forall (w : L5.range) (a : Z), In w W -> L5.in_rng w a -> CH2.wclient L sp a).
  { intros w a [<-|[]] Hin; unfold L5.in_rng in Hin; cbn [fst snd] in Hin; (split; [lia | left; lia]). }
  assert (CRS_OK : forall rg : SGP.region, In rg (CH.hd_crs G.HDECL) -> SGP.region_vars_lt GT.NF rg = true /\ (forall a : Z, CH2.in_reg E0 rg a -> CH2.sclient L LBo sp a)).
  { intros rg [<-|[<-|[]]]; (split; [vm_compute; reflexivity|]); intros a Ha; unfold CH2.in_reg, estart, elenZ in Ha; cbn [a_base a_off edenot] in Ha.
    - rewrite U14 in Ha. rewrite u64_of_Z in Ha by lia. split; [lia | left; lia].
    - rewrite ?U10, ?U11 in Ha. rewrite ?u64_of_Z in Ha by lia. split; [lia|]. right; right.
      destruct SRCB as (b & Hb & _ & B1 & B2). exists b. split; [exact Hb | lia]. }
  assert (WRS_OK : forall rg : SGP.region, In rg (CH.hd_wrs G.HDECL) -> SGP.region_vars_lt GT.NF rg = true /\ (forall a : Z, CH2.in_reg E0 rg a -> exists w : L5.range, In w W /\ L5.in_rng w a)).
  { intros rg [<-|[]]; (split; [vm_compute; reflexivity|]); intros a Ha; unfold CH2.in_reg, estart, elenZ in Ha; cbn [a_base a_off edenot] in Ha.
    rewrite U32 in Ha. rewrite u64_of_Z in Ha by lia. exists (S2, 24). split; [left; reflexivity | unfold L5.in_rng; cbn [fst snd]; lia]. }
  assert (IMG_OK : forall (rg : Z * Z) (a : Z), In rg (CH.hd_img G.HDECL) -> fst rg <= a < snd rg -> hl_img_lo L <= a < hl_img_hi L /\ ~ hl_alloc_static L a /\ ~ in_errno L a).
  { intros rg a [<-|[]] Ha. cbn [fst snd] in Ha. rewrite ILO, IHI. unfold in_errno. rewrite LER.
    split; [lia|]. split; [intros X; pose proof (PmLayout.ly_static L LAY a X); lia | lia]. }
  assert (DEF0 : L5.defined M (sp - CH.hd_scr G.HDECL) (CH.hd_scr G.HDECL)) by (rewrite SCRV; intros j Hj; apply S5; lia).
  assert (W_S2 : In (S2, 24) W) by (left; reflexivity).
  set (g := ESBU.SG rep len0).
  set (XL := fun (i : nat) (k cnt cv sl : Z) => match i with
             | O => sl = len0
             | S _ => (1 <= k <= n) /\ cnt = esc_len (firstn (Z.to_nat (n - k)) bs) /\ sl = len0 + cnt + P i /\
                      ((2 <= i)%nat -> cv = nth (Z.to_nat (n - k)) bs 0 mod 256)
             end).
  set (XIv := fun (g1 : ESBU.sghost) (i : nat) (E : env) (M1 : mem) => ESBU.sink_inv M1 S2 g1 /\ XL i (uv E KE) (uv E CNTE) (uv E CE) (ESBU.s_len g1)).
  set (CredV := ESBU.CredV L kx bx).
  set (gB := ESBU.gB []).
  assert (GBL : forall g1, gB g1 = PML.srep_blocks (ESBU.s_rep g1)) by (intros g1; unfold gB, ESBU.gB; rewrite app_nil_r; reflexivity).
  assert (NILB : forall i E, CH2.den E (nth i G.BLS []) = []).
  { intros i E. unfold G.BLS. do 38 (destruct i as [|i]; [reflexivity|]). destruct i; reflexivity. }
  assert (BRG : forall g1 M0c i E (M1 : mem) m1, CH2V.heap_ambV L HI GT.NF E0 model LBo sp G.HDECL W G.BLS ESBU.sghost gB CredV g1 M0c i E M1 m1 ->
                  (forall b, In b (gB g1) -> block_range L (fst b) (snd b)) /\ env_agree GT.NF E0 E /\ exists cr1, hi_heap HI (LBo ++ gB g1) cr1 M1 (m_vmmaps m1) /\ CredV g1 i E cr1).
  { intros g1 M0c i E M1 m1 (_ & _ & HagE & (cr1 & HH1 & HC1) & _). unfold CH2.cur, CH2V.LBr in HH1. rewrite NILB in HH1. cbn [app] in HH1.
    split; [|split; [exact HagE | exists cr1; split; [exact HH1 | exact HC1]]]. intros b Hb.
    destruct (hio_wf L SCFG HI HIok _ _ _ _ HH1) as (Hwf & _). apply (Hwf b). apply in_or_app. right. exact Hb. }
  assert (STRETCH : forall g1 M0c i c k ps t E R1 (M1 : mem) m1 E' R' (M' : mem), CH2.is_leaf G.CPS G.TAGS i c k ps t -> CC.At (hl_segs L) c E R1 M1 ->
                      CH2V.heap_ambV L HI GT.NF E0 model LBo sp G.HDECL W G.BLS ESBU.sghost gB CredV g1 M0c i E M1 m1 -> XIv g1 i E M1 ->
                      env_agree (CC.cp_nx c) E E' -> CC.leaf_facts (hl_segs L) c ps E' R' M1 M' ->
                      ESBU.sink_inv M' S2 g1 /\ env_agree GT.NF E0 E').
  { intros g1 M0c i c k ps t E R1 M1 m1 E' R' M' IL HAt HA HX Hag HLF.
    pose proof (CH2.leaves_all_sound _ _ _ leaf_ok _ _ _ _ _ IL) as X. unfold leaf_chk in X. apply andb_prop in X as [XF _].
    apply andb_prop in XF as [XF _]. apply andb_prop in XF as [XF XNF]. apply Nat.leb_le in XNF.
    destruct (BRG _ _ _ _ _ _ HA) as (HB & HagE & _).
    assert (HagE' : env_agree GT.NF E0 E') by (eapply CC.env_agree_trans; [exact HagE | eapply CC.env_agree_le; [exact Hag | exact XNF]]).
